class AtlasLanguage {
  const AtlasLanguage(this.code, this.name, this.englishName);
  final String code;
  final String name;
  final String englishName;
}
class AtlasLocalizations {
  const AtlasLocalizations._();
  static const languages = <AtlasLanguage>[
    AtlasLanguage('en','English','English'), AtlasLanguage('bn','বাংলা','Bengali'),
    AtlasLanguage('ar','العربية','Arabic'), AtlasLanguage('fa','فارسی','Persian'),
    AtlasLanguage('ru','Русский','Russian'), AtlasLanguage('zh','简体中文','Chinese (Simplified)'),
    AtlasLanguage('ja','日本語','Japanese'), AtlasLanguage('hi','हिन्दी','Hindi'),
  ];
  static final supportedLocales = languages.map((item) => Locale(item.code)).toList(growable:false);
  static String translate(String code, String source) {
    if (code == 'en') return source;
    final normalized = source.replaceAll('\n', r'\n');
    return _translations[code]?[normalized] ?? _regions[code]?[normalized] ?? source;
  }
  static const LocalizationsDelegate<AtlasLocalizations> delegate = _AtlasDelegate();
}
class _AtlasDelegate extends LocalizationsDelegate<AtlasLocalizations> {
  const _AtlasDelegate();
  @override bool isSupported(Locale locale) => AtlasLocalizations.languages.any((item) => item.code == locale.languageCode);
  @override Future<AtlasLocalizations> load(Locale locale) async => const AtlasLocalizations._();
  @override bool shouldReload(_AtlasDelegate old) => false;
}
String tr(BuildContext context, String source) => AtlasLocalizations.translate(Localizations.localeOf(context).languageCode, source);

/// App-wide native text adapter with a const constructor. It translates string copy
/// at paint/widget-build time without timers, polling, network calls, or animation.
class Text extends StatelessWidget {
  const Text(this.data, {super.key, this.style, this.strutStyle, this.textAlign, this.textDirection,
    this.locale, this.softWrap, this.overflow, this.maxLines, this.semanticsLabel,
    this.textWidthBasis, this.textHeightBehavior, this.textScaler, this.selectionColor}) : textSpan = null;
  const Text.rich(this.textSpan, {super.key, this.style, this.strutStyle, this.textAlign, this.textDirection,
    this.locale, this.softWrap, this.overflow, this.maxLines, this.textWidthBasis,
    this.textHeightBehavior, this.textScaler, this.selectionColor}) : data = null, semanticsLabel = null;
  final String? data;
  final InlineSpan? textSpan;
  final TextStyle? style;
  final StrutStyle? strutStyle;
  final TextAlign? textAlign;
  final TextDirection? textDirection;
  final Locale? locale;
  final bool? softWrap;
  final TextOverflow? overflow;
  final int? maxLines;
  final String? semanticsLabel;
  final TextWidthBasis? textWidthBasis;
  final TextHeightBehavior? textHeightBehavior;
  final TextScaler? textScaler;
  final Color? selectionColor;
  @override Widget build(BuildContext context) {
    final activeLocale = locale ?? Localizations.localeOf(context);
    final copy = data == null ? null : AtlasLocalizations.translate(activeLocale.languageCode, data!);
    if (textSpan != null) return material.Text.rich(textSpan!, style: style, strutStyle: strutStyle, textAlign: textAlign, textDirection: textDirection, locale: activeLocale, softWrap: softWrap, overflow: overflow, maxLines: maxLines, textWidthBasis: textWidthBasis, textHeightBehavior: textHeightBehavior, textScaler: textScaler, selectionColor: selectionColor);
    return material.Text(copy ?? '', style: style, strutStyle: strutStyle, textAlign: textAlign, textDirection: textDirection, locale: activeLocale, softWrap: softWrap, overflow: overflow, maxLines: maxLines, semanticsLabel: semanticsLabel, textWidthBasis: textWidthBasis, textHeightBehavior: textHeightBehavior, textScaler: textScaler, selectionColor: selectionColor);
  }
}
